# Co w oryginalnej ramce zastepujemy. Wyrazenia, nie dokladne napisy, zeby
# drobna zmiana spacji w nowej wersji panelu nie wylaczala motywu.
RE_TOP = re.compile(r'<div class="top">.*?\n<div class="wrap">', re.S)
RE_HEAD_END = re.compile(r"</style>\s*</head>\s*<body>")
RE_FOOT = re.compile(r'<div class="wrap" style="padding-top:0;text-align:center">')
RE_END = re.compile(r"</body>\s*</html>\s*$")


def patch_template(src):
    """The panel's frame with the theme in it, or None when it is not one."""
    if not isinstance(src, str) or 'class="m2p-head"' in src:
        return None
    if not (RE_TOP.search(src) and RE_HEAD_END.search(src) and RE_END.search(src)):
        return None
    out = RE_HEAD_END.sub(
        lambda _m: ('</style>\n<link rel="stylesheet" href="/m2p/theme.css?v=' + THEME_VERSION + '">\n</head>'
                    + BODY_TAG), src, count=1)
    out = RE_TOP.sub(lambda _m: HEADER, out, count=1)
    foot = RE_FOOT.search(out)
    if foot:
        out = out[:foot.start()] + FOOT_OPEN + out[foot.start():]
        out = RE_END.sub(lambda _m: FOOT_CLOSE + TAIL, out, count=1)
    else:
        out = RE_END.sub(lambda _m: TAIL, out, count=1)
    return out


