# Menu dla biezacego zapytania
# ---------------------------------------------------------------------------
def _seban_url(mod):
    front = getattr(mod, "_front_page", None)
    try:
        return front.ban_panel_url(request.host)
    except Exception:  # noqa: BLE001
        return ""


def _context(mod):
    try:
        lang = mod.lang()
    except Exception:  # noqa: BLE001
        lang = "pl"
    ep = request.endpoint or ""
    section = ""
    if ep == "m2p_section":
        section = SECTION_KEY.get((request.view_args or {}).get("slug", ""), "")
    vf = mod.app.view_functions
    admin = bool(session.get("auth"))
    if not admin:
        try:
            admin = bool(mod.local_open())
        except Exception:  # noqa: BLE001
            admin = False
    upd_new = False
    try:
        upd_new = bool(mod.update_state().get("available"))
    except Exception:  # noqa: BLE001
        pass
    market_on = False
    try:
        market = getattr(mod, "_market", None)
        market_on = bool(market is not None and market.enabled() and "market_preview" in vf)
    except Exception:  # noqa: BLE001
        market_on = False
    mt2009 = bool(getattr(mod, "ENGINE_MT2009", False))
    front = url_for("front") if "front" in vf else "/"
    discord = getattr(mod, "DISCORD_URL", "") or ""
    seban = _seban_url(mod)

    def item(key, endpoint=None, href=None, eps=(), prefix=None, sec=None, ext=False, new=False, when=True):
        if not when:
            return None
        if sec is not None:
            href = url_for("m2p_section", slug=sec)
        elif href is None:
            if endpoint not in vf:
                return None
            href = url_for(endpoint)
        if not href:
            return None
        active = (endpoint is not None and ep == endpoint) or ep in eps \
            or (prefix is not None and ep.startswith(prefix)) \
            or (sec is not None and ep == "m2p_section" and SECTION_KEY.get(sec) == section)
        return {"key": key, "label": _l(key, lang), "href": href, "active": active,
                "ext": ext, "new": new, "tip": _l("new", lang) if new else ""}

    def group(key, items):
        items = [i for i in items if i]
        return {"title": _l(key, lang), "links": items} if items else None

    if admin:
        groups = [
            group("g_world", [
                item("map", "live_map"),
                item("world", "m2p_world"),
                item("rankings2", "m2p_rankings"),
                item("chat", "m2p_chat"),
                item("maps", "m2p_maps"),
                item("items", "m2p_items"),
                item("itemdb", "m2p_itemdb"),
                item("season", "season"),
                item("guilds", "guilds_page"),
                item("decisions", "decisions_page", when=mt2009),
                item("players", sec="postacie", eps=("player", "player_from_game", "fame_ranking", "bot_exp_lock")),
            ]),
            group("g_market", [
                item("market", "market_preview", when=market_on),
                item("mstats", "m2p_market_stats"),
                item("itemshop", "m2p_itemshop"),
                item("refines", "m2p_refines"),
                item("prices", "m2p_prices"),
            ]),
            group("g_game", [
                item("rates", "rates"),
                item("ai", "ai_weights"),
                {"key": "population", "label": "Populacja botów" if lang == "pl" else "Bot population", "href": "/panel/populacja", "active": request.endpoint == "m2p_population", "ext": False, "new": False, "tip": ""},
                item("ai_items", "ai_item_policy"),
                item("events", "events_page"),
                item("fun", "m2p_fun"),
                item("editsql", "editsql_home", prefix="editsql"),
                item("drops", "drops_home", prefix="drops_",
                     when=bool(getattr(mod, "DROPS_ENABLED", False))),
                item("client", "client_data_home", prefix="client_data",
                     when=bool(getattr(mod, "CLIENT_DATA_ENABLED", False))),
            ]),
            group("g_server", [
                item("patchlog", "patchlog", eps=("update_page",), new=upd_new),
                item("perf", "m2p_perf"),
                item("export", sec="statystyki"),
                item("newacc", "m2p_new_account"),
                item("reset", sec="reset-hasla"),
                item("gamelang", sec="jezyk-gry"),
                item("pass", sec="haslo-panelu"),
            ]),
            group("g_links", [
                item("home", href=front),
                item("seban", href=seban, ext=True),
                item("discord", href=discord, ext=True),
                item("logout", "logout", when=bool(session.get("auth"))),
            ]),
        ]
    else:
        groups = [
            group("g_world", [
                item("map", "live_map"),
                item("rankings", href=front + "?s=rankings"),
                item("guildrank", href=front + "?s=guildrank"),
            ]),
            group("g_links", [
                item("home", href=front),
                item("discord", href=discord, ext=True),
                item("login", href=front + "?s=admin"),
            ]),
        ]
    groups = [g for g in groups if g]
    page = ""
    for g in groups:
        for i in g["links"]:
            if i["active"]:
                page = i["label"]
                break
        if page:
            break
    return {
        "groups": groups,
        "section": section,
        "title": _l("title", lang),
        "menu": _l("menu", lang),
        "page": page or str(getattr(mod, "BRAND", "") or "Metin2"),
        "home_href": front,
        "home_label": _l("home", lang),
        "panel_href": url_for("live_map") if "live_map" in vf else "/admin",
    }


