RE_ESQ_BOX = re.compile(
    r'<div class="boxes-middle">&nbsp;</div>\s*<div class="modul-box modul-box-2">.*?</ul>\s*</div>\s*</div>\s*</div>',
    re.S)


SIDE_BOOT = ("<script>(function(){var p='';try{p=localStorage.getItem('m2p_pal')||(document.cookie.match(/(?:^|; )m2p_pal=([^;]*)/)||[])[1]||''}catch(e){p=(document.cookie.match(/(?:^|; )m2p_pal=([^;]*)/)||[])[1]||''}"
             "var s=({red:'red',brown:'dark',blue:'blue',green:'green'})[p]||'parch';"
             "if(s!=='parch')document.body.classList.add('m2p-side-'+s)})()</script>")
RE_ESQ_FIRST = re.compile(
    r'<div class="modul-box">\s*<div class="modul-box-bg">\s*<div class="modul-box-bg-bottom">\s*'
    r'<ul class="main-nav esq-nav">.*?</ul>\s*</div>\s*</div>\s*</div>\s*', re.S)


def _palette_only(html):
    """Iwakura P18 pkt 6H: strona edytora bez naszego menu (np. przed zalogowaniem do edytora)
    też dostaje aktywny motyw, a nie pergamin."""
    if "m2p_pal" in html:
        return None
    html = html.replace("</head>", '<link rel="stylesheet" href="/m2p/side.css?v=%s">\n</head>' % THEME_VERSION, 1)
    html = re.sub(r"(<body[^>]*>)", lambda m: m.group(1) + PAL_BOOT + SIDE_BOOT, html, count=1)
    return _esq_palette(html)


def _patch_editsql(mod, html):
    if 'class="editsql-body"' not in html:
        return None
    if "m2p-box" in html:
        return _palette_only(html)
    m = RE_ESQ_BOX.search(html)
    if not m or 'href="/admin"' not in m.group(0):
        return _palette_only(html)
    ctx = _context(mod)
    groups = render_template_string(SIDE_GROUPS, m2p=ctx)
    kept = [li for li in re.findall(r"<li>.*?</li>", m.group(0), re.S)
            if 'href="/admin"' not in li and 'href="/map"' not in li]
    tail = ""
    if kept:
        tail = ('<div class="boxes-middle">&nbsp;</div><div class="modul-box modul-box-2"><div class="modul-box-bg">'
                '<div class="modul-box-bg-bottom"><ul class="main-nav" style="padding-bottom:0">%s</ul></div></div></div>'
                % "".join(kept))
    html = html[:m.start()] + groups + tail + html[m.end():]
    # Przed zalogowaniem do edytora jego wlasne pudelko ma tylko "Start edytora":
    # samotny przycisk nad naszym menu - usuwamy je, menu zaczyna sie od gory.
    # Edytor ma wlasne pudelko nawigacji nad naszym menu; przenosimy je pod menu,
    # zeby glowne menu zawsze zaczynalo sie w tym samym miejscu.
    first = RE_ESQ_FIRST.search(html)
    if first:
        box = first.group(0)
        html = html[:first.start()] + html[first.end():]
        html = re.sub(r'(<div class="boxes-top">&nbsp;</div>\s*)<div class="m2p-boxes-mid"></div>', r"\1", html, count=1)
        if len(re.findall(r"<li", box)) > 1:
            # Nawigacja edytora: osobna kolumna po prawej stronie ekranu.
            mm = re.search(r'<div class="boxes-bottom">&nbsp;</div>\s*</div>', html)
            if mm:
                col = ('<div class="col-1 m2p-esq-right"><div class="boxes-top">&nbsp;</div>' + box
                       + '<div class="boxes-bottom">&nbsp;</div></div>')
                html = html[:mm.end()] + col + html[mm.end():]
    html = html.replace("</head>", '<link rel="stylesheet" href="/m2p/side.css?v=%s">\n</head>' % THEME_VERSION, 1)
    html = re.sub(r"(<body[^>]*>)", lambda m: m.group(1) + PAL_BOOT + SIDE_BOOT, html, count=1)
    return _esq_palette(html)


# Iwakura P18 pkt 6H: wybór motywu także w stopce edytora bazy danych.
ESQ_PAL = ("<script>(function(){var f=document.getElementById('footer');if(!f)return;"
           "var pl=(document.documentElement.getAttribute('lang')||'pl').slice(0,2)==='pl';"
           "var N=pl?['Motyw','pergamin','czerwony','brązowy','niebieski','zielony','1963']:['Theme','parchment','red','brown','blue','green','1963'];"
           "var K=['parch','red','brown','blue','green','1963'],c='parch';"
           "try{c=localStorage.getItem('m2p_pal')||(document.cookie.match(/(?:^|; )m2p_pal=([^;]*)/)||[])[1]||'parch'}catch(e){}"
           "var d=document.createElement('div');d.className='m2p-pal';"
           "d.innerHTML=N[0]+': '+K.map(function(k,i){return '<a data-p=\"'+k+'\"'+(k===c?' class=\"on\"':'')+'>'+N[i+1]+'</a>'}).join('|');"
           "d.addEventListener('click',function(e){var a=e.target.closest('a[data-p]');if(!a)return;var k=a.getAttribute('data-p');"
           "try{localStorage.setItem('m2p_pal',k)}catch(_){}document.cookie='m2p_pal='+k+'; path=/; max-age=31536000; SameSite=Lax';location.reload()});"
           "f.appendChild(d)})()</script>")


def _esq_extras(mod, html):
    """Iwakura P19: w edytorze bazy – przełącznik trybu szybkiego (zapis bez podglądu) i odnośniki
    do zawartości skrzynki / dropu potwora (pliki special_item_group / mob_drop_item).
    The switch is a POST form: it changes how every later save behaves, so it
    goes under the panel's CSRF check like any other change."""
    try:
        from flask import request as _rq, session as _ss
        path = _rq.path or ""
        fast = bool(_ss.get("esq_fast"))
        pl = (mod.lang() if hasattr(mod, "lang") else "pl") == "pl"
        token = mod.csrf_token()
    except Exception:  # noqa: BLE001
        return html
    if "m2p-esq-fast" in html or "<h2>" not in html:
        return html
    bar = ('<form method="post" action="/editsql-fast" class="m2p-esq-fast">%s '
           '<input type="hidden" name="_csrf" value="%s"><input type="hidden" name="on" value="%d">'
           '<input type="hidden" name="next" value="%s"><button type="submit" class="%s">%s</button></form>'
           % (("Tryb szybki (zapis bez podglądu):" if pl else "Fast mode (save without preview):"),
              escape(token), 0 if fast else 1, escape(path), "on" if fast else "",
              ("WŁĄCZONY – wyłącz" if pl else "ON – switch off") if fast else ("wyłączony – włącz" if pl else "off – switch on")))
    m = re.match(r"^/editsql/(chests|drops|mobs)/[^/]+/(\d+)", path)
    if m and "drops_home" in mod.app.view_functions:
        kind, vnum = m.group(1), m.group(2)
        if kind == "chests":
            bar += ('<div class="esq-note esq-note-info"><b><a href="/drops/chests/g/%s">%s →</a></b> %s</div>'
                    % (vnum, "Edytuj zawartość tej skrzynki" if pl else "Edit this chest's contents",
                       "(przedmioty w środku, szanse, ilości – edytor „Skrzynki i drop”)." if pl else
                       "(the items inside, chances, counts – the “Chests and drops” editor)."))
        else:
            bar += ('<div class="esq-note esq-note-info"><b><a href="/drops/mobs?q=%s">%s →</a></b> %s</div>'
                    % (vnum, "Edytuj drop tego potwora" if pl else "Edit this monster's drop",
                       "(grupy dropu mob_drop_item – edytor „Skrzynki i drop”). Tu zmieniasz tylko kolumnę drop_item." if pl else
                       "(mob_drop_item's drop groups – the “Chests and drops” editor). Here you change only the drop_item column."))
    return html.replace("<h2>", bar + "<h2>", 1)


def _esq_palette(html):
    if "m2p-esq-pal" in html or "</body>" not in html:
        return html
    css = ("<style id=\"m2p-esq-pal\">#footer .m2p-pal{margin-top:6px;font-size:11px;color:#c9b48a;text-align:center}"
           "#footer .m2p-pal a{cursor:pointer;margin:0 4px;color:#e8d49a}"
           "#footer .m2p-pal a.on{color:#fff1b8;font-weight:bold;text-decoration:underline}</style>")
    spark = ("<script>[].forEach.call(document.querySelectorAll('.col-1 .boxes-middle,.m2p-boxes-mid'),function(e){"
             "e.style.setProperty('--m2p-sd',(4.5+Math.random()*5).toFixed(2)+'s');e.style.setProperty('--m2p-sdl',(Math.random()*6).toFixed(2)+'s')})</script>")
    return html.replace("</body>", css + ESQ_PAL + spark + "</body>", 1)


