def _patch_front(mod, app):
    front = getattr(mod, "_front_page", None)
    if front is None:
        return
    try:
        front.S["m_map"] = dict(L["title"])
        front.S["m_ban"] = dict(L["seban"])
    except Exception:  # noqa: BLE001
        app.logger.exception("m2_theme: front page labels")
        return
    old_menu = getattr(front, "_menu", None)

    def _menu(lang, ctx):
        try:
            items = [
                ("m_map", front.MAP_URL, False, False),
                ("m_ban", front.ban_panel_url(request.host), True, False),
                ("m_discord", mod.DISCORD_URL, True, False),
                ("m_github", front.GITHUB_URL, True, False),
                ("m_editsql", "/editsql", False, False),
                ("m_adminpw", url_for("front", s="admin"), False, ctx.get("page") == "admin"),
            ]
            out = []
            for key, href, ext, active in items:
                out.append('<li%s><a href="%s"%s%s>%s</a></li>' % (
                    ' class="active"' if active else "", escape(href), ' class="m2p-pulse"' if key == "m_map" else "",
                    ' target="_blank" rel="noopener noreferrer"' if ext else "", front.e(key, lang)))
            return "\n".join(out)
        except Exception:  # noqa: BLE001
            app.logger.exception("m2_theme: front page menu")
            return old_menu(lang, ctx) if old_menu else ""

    front._menu = _menu


