RE_MK_EXPIRED = re.compile(r'\n(\s*)<label class="mk-check"><input type="checkbox" id="mk-expired">')


MK_SHOWBON = ('<div class="mk-f mk-f-showbon"><label class="mk-check"><input type="checkbox" id="mk-showbon">{{ T.f_showbon }}</label></div>')
MK_SHOWBON_JS = """<script>(function(){var c=document.getElementById('mk-showbon'),l=document.getElementById('mk-list');if(!c||!l)return;
var on=false;try{on=localStorage.getItem('m2p_mk_bon')==='1'}catch(e){}c.checked=on;l.classList.toggle('mk-showbon',on);
c.addEventListener('change',function(){l.classList.toggle('mk-showbon',c.checked);try{localStorage.setItem('m2p_mk_bon',c.checked?'1':'0')}catch(e){}});})();</script>
<style>.mk-showbon .mk-bon-list{display:block!important}.mk-showbon .mk-bon>.mk-btn2{background:#8e1d11!important;color:#fff3cf!important;border-color:#c99a48!important}
.mk-f-showbon{padding-bottom:8px;border-bottom:1px dashed rgba(160,120,60,.45)}.mk-f-showbon .mk-check{font-weight:bold}</style>"""


def _patch_market(mod, app):
    market = getattr(mod, "_market", None)
    page = getattr(market, "page", None) if market is not None else None
    body = getattr(page, "BODY", None)
    if not isinstance(body, str):
        return
    try:
        texts = getattr(market, "texts", None)
        if texts is not None and "f_showbon" not in texts.TEXTS:
            texts.TEXTS["f_showbon"] = ("Wyświetlaj bonusy", "Show bonuses")
    except Exception:  # noqa: BLE001
        pass
    i = body.find('id="mk-expired"')
    if i >= 0:
        line_start = body.rfind("\n", 0, i)
        if '<div class="mk-f">' not in body[line_start:i]:
            body = RE_MK_EXPIRED.sub(
                lambda m: '\n' + m.group(1) + '<div class="mk-f"><label class="mk-check"><input type="checkbox" id="mk-expired">',
                body, count=1)
    # "Postac:" nad lista ofert - zbedne (zostaje sama lista wyboru)
    body = re.sub(r'<label class="mk-muted" for="mk-me"[^>]*>\{\{ T\.character \}\}:</label>', "", body, count=1)
    # pierwszy filtr: "Wyswietlaj bonusy"
    if 'id="mk-showbon"' not in body:
        body = body.replace('<div class="mk-sec">{{ T.filters }}</div>', '<div class="mk-sec">{{ T.filters }}</div>' + MK_SHOWBON, 1)
        body = body + MK_SHOWBON_JS
    page.BODY = body
    app.logger.info("m2_theme: market preview markup patched")


