# ---------------------------------------------------------------------------
# Statystyki rynku (/panel/rynek). Dane: migawki kolektora Panelu Sebana
# (web_seban_shop_snapshot, web_seban_shop_item_snapshot, web_seban_metric_snapshot)
# i log sprzedazy ze straganow (log.log how='PLAYERBOT_STALL_SOLD').
# ---------------------------------------------------------------------------
SALE_HINT_RE = re.compile(r"^(\d+)\s+x(\d+)\s+za\s+(\d+)$")
_MSTATS_CACHE = {}

MSTATS_BODY = """
<div class="card m2p-ms-head">
<h3>{{ m2p_ms.title }}</h3>
<div class="m2p-ms-bar"><p class="muted" id="msWhen">{{ m2p_ms.loading }}</p>
<div class="m2p-rng" id="msRng"><button type="button" data-r="24h">24 h</button><button type="button" data-r="7d">7 d</button><button type="button" data-r="14d">14 d</button><button type="button" data-r="30d">30 d</button></div></div>
</div>
<div class="m2p-ms" id="m2pMs" data-lang="{{ curlang }}"></div>
"""


def _ms_text(mod, value):
    try:
        return mod.log_text(value)
    except Exception:  # noqa: BLE001
        return value.decode("utf-8", "replace") if isinstance(value, (bytes, bytearray)) else str(value or "")


def _ms_item_name(mod, vnum, lang):
    try:
        return mod.localized_item_name(vnum, lang) or ("VNUM %d" % vnum)
    except Exception:  # noqa: BLE001
        return "VNUM %d" % vnum


def market_stats(mod, rng, lang):
    span = METRIC_RANGES.get(rng, METRIC_RANGES["7d"])
    bucket = max(300, span // 160)
    out = {"ok": True, "range": rng, "kpi": {}, "empires": [], "value_trend": [], "yang": [], "shops_trend": [],
           "sales_trend": [], "top_sold": [], "top_listed": [], "recent": [], "latest": None, "missing": []}
    with mod.db() as c, c.cursor() as cur:
        def q(sql, args=(), one=False):
            cur.execute(sql, args)
            return cur.fetchone() if one else cur.fetchall()
        # sklepy teraz - po krolestwach
        try:
            latest = (q("SELECT MAX(captured_at) AS t FROM player.web_seban_shop_snapshot", one=True) or {}).get("t")
            out["latest"] = latest.strftime("%Y-%m-%d %H:%M") if latest else None
            emp = {}
            if latest:
                for r in q("SELECT empire, SUM(shop_count) AS shops, SUM(offer_count) AS offers, SUM(item_count) AS items, "
                           "SUM(total_value) AS value FROM player.web_seban_shop_snapshot WHERE captured_at=%s GROUP BY empire",
                           (latest,)):
                    emp[int(r["empire"] or 0)] = {k: int(r[k] or 0) for k in ("shops", "offers", "items", "value")}
            out["empires"] = [dict(id=e, **emp.get(e, {"shops": 0, "offers": 0, "items": 0, "value": 0})) for e in (1, 2, 3)]
            k = out["kpi"]
            for key in ("shops", "offers", "items", "value"):
                k[key] = sum(e[key] for e in out["empires"])
            rows = q("SELECT FLOOR(UNIX_TIMESTAMP(captured_at) / %s) * %s AS t, empire, AVG(v) AS v FROM ("
                     " SELECT captured_at, empire, SUM(total_value) AS v FROM player.web_seban_shop_snapshot"
                     " WHERE captured_at >= NOW() - INTERVAL %s SECOND GROUP BY captured_at, empire) x"
                     " GROUP BY t, empire ORDER BY t", (bucket, bucket, span))
            series = {1: [], 2: [], 3: []}
            for r in rows:
                e = int(r["empire"] or 0)
                if e in series:
                    series[e].append([int(r["t"]), int(r["v"] or 0)])
            out["value_trend"] = [{"id": e, "pts": series[e]} for e in (1, 2, 3)]
        except Exception:  # noqa: BLE001
            out["missing"].append("shops")
        # yang w obiegu i liczba sklepow w czasie
        try:
            for name, key in (("total_yang", "yang"), ("shops_count", "shops_trend")):
                out[key] = [[int(r["t"]), int(r["v"] or 0)] for r in q(
                    "SELECT FLOOR(UNIX_TIMESTAMP(captured_at) / %s) * %s AS t, MAX(value) AS v FROM player.web_seban_metric_snapshot "
                    "WHERE metric=%s AND captured_at >= NOW() - INTERVAL %s SECOND GROUP BY t ORDER BY t",
                    (bucket, bucket, name, span))]
            last = q("SELECT value FROM player.web_seban_metric_snapshot WHERE metric='total_yang' "
                     "ORDER BY captured_at DESC LIMIT 1", one=True)
            out["kpi"]["yang"] = int(last["value"]) if last else None
            if out["yang"]:
                out["kpi"]["yang_delta"] = (out["kpi"]["yang"] or 0) - out["yang"][0][1]
        except Exception:  # noqa: BLE001
            out["missing"].append("metrics")
        # sprzedaze: liczba w czasie, top 24h, ostatnie
        try:
            out["sales_trend"] = [[int(r["t"]), int(r["n"])] for r in q(
                "SELECT FLOOR(UNIX_TIMESTAMP(time) / %s) * %s AS t, COUNT(*) AS n FROM log.log "
                "WHERE how='PLAYERBOT_STALL_SOLD' AND time >= NOW() - INTERVAL %s SECOND GROUP BY t ORDER BY t",
                (bucket, bucket, span))]
            agg, sales24, revenue24 = {}, 0, 0
            for r in q("SELECT vnum, hint, time FROM log.log WHERE how='PLAYERBOT_STALL_SOLD' "
                       "AND time >= NOW() - INTERVAL 24 HOUR"):
                m = SALE_HINT_RE.match(_ms_text(mod, r.get("hint")).strip())
                if not m:
                    continue
                vnum, qty, price = int(m.group(1)), int(m.group(2)), int(m.group(3))
                a = agg.setdefault(vnum, {"sales": 0, "units": 0, "revenue": 0})
                a["sales"] += 1
                a["units"] += qty
                a["revenue"] += price
                sales24 += 1
                revenue24 += price
            out["kpi"]["sales_24h"] = sales24
            out["kpi"]["revenue_24h"] = revenue24
            ranked = sorted(agg.items(), key=lambda kv: (kv[1]["sales"], kv[1]["revenue"]), reverse=True)[:15]
            out["top_sold"] = [{"vnum": v, "name": _ms_item_name(mod, v, lang), "sales": a["sales"], "units": a["units"],
                                "revenue": a["revenue"], "avg": round(a["revenue"] / a["units"]) if a["units"] else 0,
                                "per_h": round(a["sales"] / 24.0, 1)} for v, a in ranked]
            rec = q("SELECT time, who, vnum, hint FROM log.log WHERE how='PLAYERBOT_STALL_SOLD' ORDER BY time DESC LIMIT 150")
            who = sorted({int(r["who"] or 0) for r in rec})
            names = {}
            if who:
                for r in q(mod.bot_sql("SELECT p.id, p.name, <<EMPIRE_P>> AS empire FROM player.player p WHERE p.id IN ("
                                       + ",".join(["%s"] * len(who)) + ")"), tuple(who)):
                    names[int(r["id"])] = (_ms_text(mod, r["name"]), int(r["empire"] or 0))
            for r in rec:
                m = SALE_HINT_RE.match(_ms_text(mod, r.get("hint")).strip())
                vnum = int(m.group(1)) if m else int(r["vnum"] or 0)
                nm, em = names.get(int(r["who"] or 0), ("pid %s" % r["who"], 0))
                out["recent"].append({"time": r["time"].strftime("%d.%m %H:%M:%S") if r.get("time") else "",
                                      "vnum": vnum, "name": _ms_item_name(mod, vnum, lang),
                                      "qty": int(m.group(2)) if m else 1, "price": int(m.group(3)) if m else 0,
                                      "seller": nm, "seller_id": int(r["who"] or 0), "empire": em})
            out["kpi"]["sales_total"] = int((q("SELECT COUNT(*) AS n FROM log.log WHERE how='PLAYERBOT_STALL_SOLD'",
                                               one=True) or {}).get("n") or 0)
        except Exception:  # noqa: BLE001
            out["missing"].append("sales")
        # najczesciej wystawiane teraz, z trendem do sprzed 24 h
        try:
            lt = (q("SELECT MAX(captured_at) AS t FROM player.web_seban_shop_item_snapshot", one=True) or {}).get("t")
            if lt:
                top = q("SELECT vnum, SUM(offers) AS offers, SUM(total_units) AS units, SUM(total_value) AS value "
                        "FROM player.web_seban_shop_item_snapshot WHERE captured_at=%s GROUP BY vnum "
                        "ORDER BY units DESC LIMIT 15", (lt,))
                vn = [int(r["vnum"]) for r in top]
                base = {}
                if vn:
                    b0 = q("SELECT MIN(captured_at) AS t FROM player.web_seban_shop_item_snapshot "
                           "WHERE captured_at >= NOW() - INTERVAL 24 HOUR", one=True)
                    if b0 and b0.get("t"):
                        for r in q("SELECT vnum, SUM(total_units) AS units, SUM(total_value) AS value "
                                   "FROM player.web_seban_shop_item_snapshot WHERE captured_at=%s AND vnum IN ("
                                   + ",".join(["%s"] * len(vn)) + ") GROUP BY vnum", (b0["t"],) + tuple(vn)):
                            base[int(r["vnum"])] = (int(r["units"] or 0), int(r["value"] or 0))
                for r in top:
                    v, units, value = int(r["vnum"]), int(r["units"] or 0), int(r["value"] or 0)
                    avg = round(value / units) if units else 0
                    bu, bv = base.get(v, (None, None))
                    bavg = round(bv / bu) if bu else None
                    out["top_listed"].append({"vnum": v, "name": _ms_item_name(mod, v, lang), "offers": int(r["offers"] or 0),
                                              "units": units, "avg": avg,
                                              "units_trend": 0 if bu is None else (units > bu) - (units < bu),
                                              "price_trend": 0 if bavg is None else (avg > bavg) - (avg < bavg)})
        except Exception:  # noqa: BLE001
            out["missing"].append("items")
    return out


