RE_GAME_LINK = re.compile(r"\|H[^|]*\|h(.*?)\|h", re.S)
RE_GAME_COLOR = re.compile(r"\|c[0-9a-fA-F]{8}|\|r|\|h|\|H")


def clean_chat(text, name=""):
    """Kody czatu gry (|Hmsg:nick,1|hnick|h|r, |cFFxxxxxx) zamienione na zwykly tekst."""
    text = RE_GAME_LINK.sub(lambda m: m.group(1), text or "")
    text = RE_GAME_COLOR.sub("", text).strip()
    for pre in ("[" + name + "]:", "[" + name + "] :", name + " : ", name + ": ", name + ":"):
        if name and text.startswith(pre):
            text = text[len(pre):].strip()
            break
    return text


def chat_messages(mod, limit=100):
    out, ids = [], set()
    with mod.db() as c, c.cursor() as cur:
        try:
            cur.execute("SELECT c.who_id AS pid, c.who_name AS name, c.type, CAST(c.msg AS BINARY) AS msg, c.`when` AS t FROM log.chat_log c "
                        "WHERE c.type IN ('SHOUT','TRADE','NORMAL') ORDER BY c.`when` DESC LIMIT %s", (limit,))
            for r in cur.fetchall():
                out.append({"pid": int(r["pid"] or 0), "name": _ms_text(mod, r["name"]), "type": _ms_text(mod, r["type"]) or "SHOUT",
                            "msg": _ms_text(mod, r["msg"]), "t": r["t"]})
        except Exception:  # noqa: BLE001
            pass
        try:
            cur.execute("SELECT pid, name, message AS msg, captured_at AS t FROM player.web_seban_bot_chat_log "
                        "ORDER BY captured_at DESC LIMIT %s", (limit,))
            for r in cur.fetchall():
                out.append({"pid": int(r["pid"] or 0), "name": _ms_text(mod, r["name"]), "type": "SHOUT",
                            "msg": _ms_text(mod, r["msg"]), "t": r["t"], "bot": True})
        except Exception:  # noqa: BLE001
            pass
        ids = sorted({m["pid"] for m in out if m["pid"]})
        info = {}
        if ids:
            try:
                cur.execute(mod.bot_sql("SELECT p.id, p.name, p.job, <<EMPIRE_P>> AS empire, <<BOT_P_2>> AS is_bot FROM player.player p "
                                        "WHERE p.id IN (" + ",".join(["%s"] * len(ids)) + ")"), tuple(ids))
                for r in cur.fetchall():
                    info[int(r["id"])] = r
            except Exception:  # noqa: BLE001
                pass
    seen, res = set(), []
    for m in sorted(out, key=lambda m: m["t"] or 0):
        who = info.get(m["pid"]) or {}
        name = _ms_text(mod, who.get("name")) or m["name"] or "?"
        text = clean_chat(m["msg"] or "", name)
        if m["name"] and m["name"] != name:
            text = clean_chat(text, m["name"])
        if not text:
            continue
        key = (m["pid"], str(m["t"]), text)
        if key in seen:
            continue
        seen.add(key)
        res.append({"time": m["t"].strftime("%H:%M:%S") if hasattr(m["t"], "strftime") else str(m["t"])[11:19],
                    "pid": m["pid"], "name": name, "type": m["type"], "msg": text,
                    "empire": int(who.get("empire") or 0), "job": int(who.get("job") or 0),
                    "bot": bool(who.get("is_bot")) if who else bool(m.get("bot"))})
    return res[-limit:]


