def _q(mod, sql, args=(), one=False):
    with mod.db() as c, c.cursor() as cur:
        cur.execute(sql, args)
        return cur.fetchone() if one else cur.fetchall()


def _names_by_pid(mod, pids):
    pids = sorted({int(p) for p in pids if p})
    if not pids:
        return {}
    out = {}
    try:
        for r in _q(mod, mod.bot_sql("SELECT p.id, p.name, p.job, <<EMPIRE_P>> AS empire, <<BOT_P_2>> AS is_bot "
                                     "FROM player.player p WHERE p.id IN (" + ",".join(["%s"] * len(pids)) + ")"), tuple(pids)):
            out[int(r["id"])] = {"name": _ms_text(mod, r["name"]), "empire": int(r["empire"] or 0),
                                 "bot": bool(int(r.get("is_bot") or 0)),
                                 "job": _job(mod, r.get("job"))}
    except Exception:  # noqa: BLE001
        pass
    return out


def _job(mod, job):
    try:
        return mod.localized_job_name(int(job or 0))
    except Exception:  # noqa: BLE001
        return ""


def _proto(mod):
    try:
        mod._load_item_proto()
    except Exception:  # noqa: BLE001
        pass
    return getattr(mod, "ITEM_NAMES_PL", {}) or {}, getattr(mod, "ITEM_BASE", {}) or {}


def _iname(mod, vnum, lang):
    return _ms_item_name(mod, int(vnum or 0), lang)


def _bucket(span, n=160, low=60):
    return max(low, span // n)


# ---- ulepszenia +7 / +8 / +9 ----
def refine_data(mod, ok, lang, limit=150, plus=0):
    names, _base = _proto(mod)
    by_name = {}
    for v, n in names.items():
        by_name.setdefault(n, v)
    rows = _q(mod, "SELECT r.pid, r.item_id, CAST(r.item_name AS BINARY) AS item_name, r.step, r.time, CAST(r.setType AS BINARY) AS set_type FROM log.refinelog r "
                   "WHERE r.is_success=%s AND r.step IN (" + (str(int(plus) - 1) if plus in (7, 8, 9) else "6,7,8") + ") "
                   "ORDER BY r.time DESC LIMIT %s",
              (1 if ok else 0, int(limit)))
    who = _names_by_pid(mod, [r["pid"] for r in rows])
    try:
        bon = refine_bonuses(mod, rows, lang) if ok else {}
    except Exception:  # noqa: BLE001
        bon = {}
    out = []
    for ri, r in enumerate(rows):
        pre = _ms_text(mod, r.get("item_name")).strip()
        step = int(r.get("step") or 0)
        base = re.sub(r"\+\d+$", "", pre)
        target = "%s+%d" % (base, step + 1)
        vnum = by_name.get(target) or by_name.get(pre) or 0
        st = _ms_text(mod, r.get("set_type"))
        mvnum, method = 0, ""
        if st in REFINE_METHODS:
            method = REFINE_METHODS[st][0 if lang == "pl" else 1]
        elif st.startswith("SCROLL:") and st[7:].isdigit():
            mvnum = int(st[7:])
            method = _iname(mod, mvnum, lang)
        w = who.get(int(r["pid"] or 0), {})
        out.append({"time": r["time"].strftime("%d.%m %H:%M:%S") if r.get("time") else "", "pid": int(r["pid"] or 0),
                    "name": w.get("name") or ("pid %s" % r["pid"]), "empire": w.get("empire", 0), "bot": w.get("bot", True),
                    "job": w.get("job", ""), "item": target if ok else pre, "from": pre, "plus": step + 1, "vnum": vnum,
                    "method": method or st or "—", "method_vnum": mvnum, "kind": st.split(":")[0] if st else "",
                    "attrs": (bon.get(ri) or {}).get("attrs", []), "sockets": (bon.get(ri) or {}).get("sockets", [])})
    stats = []
    try:
        for r in _q(mod, "SELECT step, is_success, COUNT(*) AS n FROM log.refinelog WHERE time >= NOW() - INTERVAL 7 DAY "
                         "AND step IN (6,7,8) GROUP BY step, is_success"):
            stats.append([int(r["step"]) + 1, int(r["is_success"]), int(r["n"])])
    except Exception:  # noqa: BLE001
        pass
    return {"ok": True, "rows": out, "stats": stats}


# ---- itemshop ----
def itemshop_data(mod, lang):
    out = {"ok": True, "totals": {}, "top_cash": [], "top_mark": [], "recent": [], "popular": [], "daily": []}
    try:
        r = _q(mod, "SELECT COALESCE(SUM(cash),0) AS cash, COALESCE(SUM(cash_mark),0) AS mark, "
                    "COALESCE(SUM(cash>0),0) AS ca, COALESCE(SUM(cash_mark>0),0) AS ma FROM account.account", one=True)
        mark_col = True
    except Exception:  # noqa: BLE001
        r = _q(mod, "SELECT COALESCE(SUM(cash),0) AS cash, 0 AS mark, COALESCE(SUM(cash>0),0) AS ca, 0 AS ma FROM account.account", one=True)
        mark_col = False
    out["totals"] = {k: int(r[k] or 0) for k in ("cash", "mark", "ca", "ma")}
    cols = "a.login, (SELECT p.name FROM player.player p WHERE p.account_id=a.id ORDER BY p.level DESC, p.id LIMIT 1) AS pname, " \
           "(SELECT p.id FROM player.player p WHERE p.account_id=a.id ORDER BY p.level DESC, p.id LIMIT 1) AS ppid, " \
           "a.cash, " + ("a.cash_mark" if mark_col else "0") + " AS mark"
    out["top_cash"] = [{"pid": int(x.get("ppid") or 0), "login": _ms_text(mod, x.get("pname") or x["login"]), "cash": int(x["cash"] or 0), "mark": int(x["mark"] or 0)}
                       for x in _q(mod, "SELECT " + cols + " FROM account.account a WHERE a.cash>0 ORDER BY a.cash DESC LIMIT 15")]
    if mark_col:
        out["top_mark"] = [{"pid": int(x.get("ppid") or 0), "login": _ms_text(mod, x.get("pname") or x["login"]), "cash": int(x["cash"] or 0), "mark": int(x["mark"] or 0)}
                           for x in _q(mod, "SELECT " + cols + " FROM account.account a WHERE a.cash_mark>0 ORDER BY a.cash_mark DESC LIMIT 15")]
    try:
        rec = _q(mod, "SELECT pid, vnum, time FROM log.itemshop ORDER BY time DESC LIMIT 60")
        who = _names_by_pid(mod, [x["pid"] for x in rec])
        for x in rec:
            w = who.get(int(x["pid"] or 0), {})
            out["recent"].append({"time": x["time"].strftime("%d.%m %H:%M") if x.get("time") else "", "pid": int(x["pid"] or 0),
                                  "name": w.get("name") or ("pid %s" % x["pid"]), "empire": w.get("empire", 0),
                                  "vnum": int(x["vnum"] or 0), "item": _iname(mod, x["vnum"], lang)})
        out["popular"] = [{"vnum": int(x["vnum"]), "item": _iname(mod, x["vnum"], lang), "n": int(x["n"])}
                          for x in _q(mod, "SELECT vnum, COUNT(*) AS n FROM log.itemshop GROUP BY vnum ORDER BY n DESC LIMIT 15")]
        # Iwakura P18: wszystkie 30 dni (dni bez zakupów = 0), inaczej 2 punkty rozjeżdżały wykres
        import datetime as _dt
        per_day = {x["d"]: int(x["n"]) for x in _q(mod, "SELECT DATE(time) AS d, COUNT(*) AS n FROM log.itemshop "
                                                         "WHERE time >= CURDATE() - INTERVAL 29 DAY GROUP BY d")}
        today = _dt.date.today()
        out["daily"] = [[int(_time.mktime(dd.timetuple())), per_day.get(dd, 0)]
                        for dd in (today - _dt.timedelta(days=i) for i in range(29, -1, -1))]
        out["totals"]["buys"] = int((_q(mod, "SELECT COUNT(*) AS n FROM log.itemshop", one=True) or {}).get("n") or 0)
        out["totals"]["buys24"] = int((_q(mod, "SELECT COUNT(*) AS n FROM log.itemshop WHERE time >= NOW() - INTERVAL 1 DAY",
                                          one=True) or {}).get("n") or 0)
    except Exception:  # noqa: BLE001
        out["no_log"] = True
    return out


# ---- przedmioty w obiegu ----
def items_data(mod, lang, query=""):
    names, _b = _proto(mod)
    latest = (_q(mod, "SELECT MAX(captured_at) AS t FROM player.web_seban_item_snapshot", one=True) or {}).get("t")
    if not latest:
        return {"ok": True, "rows": [], "latest": None}
    base = (_q(mod, "SELECT MIN(captured_at) AS t FROM player.web_seban_item_snapshot "
                    "WHERE captured_at >= NOW() - INTERVAL 24 HOUR", one=True) or {}).get("t")
    where, args = "", ()
    q = (query or "").strip().lower()
    if q:
        vn = [v for v, n in names.items() if q in n.lower() or q == str(v)][:300]
        if not vn:
            return {"ok": True, "rows": [], "latest": latest.strftime("%Y-%m-%d %H:%M")}
        where, args = " AND vnum IN (" + ",".join(["%s"] * len(vn)) + ")", tuple(vn)
    now = _q(mod, "SELECT vnum, SUM(amount) AS a FROM player.web_seban_item_snapshot WHERE captured_at=%s" + where +
             " GROUP BY vnum ORDER BY a DESC LIMIT 120", (latest,) + args)
    prev = {}
    if base and now:
        vv = tuple(int(r["vnum"]) for r in now)
        for r in _q(mod, "SELECT vnum, SUM(amount) AS a FROM player.web_seban_item_snapshot WHERE captured_at=%s AND vnum IN ("
                         + ",".join(["%s"] * len(vv)) + ") GROUP BY vnum", (base,) + vv):
            prev[int(r["vnum"])] = int(r["a"] or 0)
    total = (_q(mod, "SELECT COUNT(DISTINCT vnum) AS n, COALESCE(SUM(amount),0) AS a FROM player.web_seban_item_snapshot "
                     "WHERE captured_at=%s", (latest,), one=True) or {})
    rows = []
    for r in now:
        v, a = int(r["vnum"]), int(r["a"] or 0)
        rows.append({"vnum": v, "item": _iname(mod, v, lang), "amount": a,
                     "delta": (a - prev[v]) if v in prev else None})
    return {"ok": True, "rows": rows, "latest": latest.strftime("%Y-%m-%d %H:%M"),
            "kinds": int(total.get("n") or 0), "units": int(total.get("a") or 0)}


def item_history(mod, vnum, span):
    b = _bucket(span)
    pts = _q(mod, "SELECT FLOOR(UNIX_TIMESTAMP(captured_at) / %s) * %s AS t, MAX(a) AS v FROM ("
                  " SELECT captured_at, SUM(amount) AS a FROM player.web_seban_item_snapshot WHERE vnum=%s"
                  " AND captured_at >= NOW() - INTERVAL %s SECOND GROUP BY captured_at) x GROUP BY t ORDER BY t",
             (b, b, int(vnum), span))
    return [[int(p["t"]), int(p["v"] or 0)] for p in pts]


# ---- baza przedmiotow ----
def itemdb_data(mod, lang, query="", itype=None, page=0, per=60):
    names, base = _proto(mod)
    q = (query or "").strip().lower()
    vnums = sorted(v for v in names if v in base)
    if q:
        vnums = [v for v in vnums if q in names[v].lower() or q == str(v)]
    counts = {}
    for v in vnums:
        t = base[v].get("type", 0)
        counts[t] = counts.get(t, 0) + 1
    if itype is not None:
        vnums = [v for v in vnums if base[v].get("type", 0) == itype]
    total = len(vnums)
    pagev = vnums[page * per:(page + 1) * per]
    extra = {}
    if pagev:
        marks = ",".join(["%s"] * len(pagev))
        for cols in ("vnum, gold, shop_buy_price, refined_vnum, refine_set", "vnum, gold, shop_buy_price", "vnum"):
            try:
                for r in _q(mod, "SELECT " + cols + " FROM player.item_proto WHERE vnum IN (" + marks + ")", tuple(pagev)):
                    extra[int(r["vnum"])] = r
                break
            except Exception:  # noqa: BLE001
                continue
    market = getattr(mod, "_market", None)
    rows = []
    for v in pagev:
        b = base[v]
        t, st = b.get("type", 0), b.get("subtype", 0)
        stats = []
        if t == 1:
            stats.append("Atak %d–%d" % (b.get("value3", 0), b.get("value4", 0)))
            if b.get("value1") or b.get("value2"):
                stats.append("Atak mag. %d–%d" % (b.get("value1", 0), b.get("value2", 0)))
        elif t == 2 and st in (0, 1, 2, 4) and b.get("value1"):
            stats.append("Obrona %d" % b.get("value1", 0))
        for ap in b.get("apply") or []:
            label = None
            try:
                label = market.apply_label(ap["type"], ap["val"], lang) if market is not None else None
            except Exception:  # noqa: BLE001
                label = None
            stats.append(label or ("#%d +%d" % (ap["type"], ap["val"])))
        e = extra.get(v, {})
        rows.append({"vnum": v, "name": names[v], "type": ITEM_TYPE_NAMES.get(t, str(t)),
                     "sub": ITEM_SUBTYPE_NAMES.get(t, {}).get(st, ""), "level": b.get("level", 0),
                     "size": (getattr(mod, "ITEM_SIZES", {}) or {}).get(v, 1), "stats": stats,
                     "buy": int(e.get("gold") or 0), "sell": int(e.get("shop_buy_price") or 0),
                     "next": int(e.get("refined_vnum") or 0)})
    return {"ok": True, "rows": rows, "total": total, "page": page, "per": per,
            "types": [{"id": k, "name": ITEM_TYPE_NAMES.get(k, str(k)), "n": n} for k, n in sorted(counts.items())]}


# ---- aktywnosc map ----
def maps_data(mod, span):
    b = _bucket(span, 140, 300)
    rows = _q(mod, "SELECT FLOOR(UNIX_TIMESTAMP(captured_at) / %s) * %s AS t, map_index, AVG(c) AS v FROM ("
                   " SELECT captured_at, map_index, SUM(character_count) AS c FROM player.web_seban_map_snapshot"
                   " WHERE captured_at >= NOW() - INTERVAL %s SECOND GROUP BY captured_at, map_index) x"
                   " GROUP BY t, map_index ORDER BY t", (b, b, span))
    series = {}
    for r in rows:
        series.setdefault(int(r["map_index"]), []).append([int(r["t"]), round(float(r["v"] or 0), 1)])
    latest = (_q(mod, "SELECT MAX(captured_at) AS t FROM player.web_seban_map_snapshot", one=True) or {}).get("t")
    now = {}
    if latest:
        for r in _q(mod, "SELECT map_index, channel, character_count AS c FROM player.web_seban_map_snapshot WHERE captured_at=%s",
                    (latest,)):
            m = now.setdefault(int(r["map_index"]), {"total": 0, "ch": {}})
            m["total"] += int(r["c"] or 0)
            m["ch"][int(r["channel"] or 1)] = int(r["c"] or 0)
    maps = sorted(set(series) | set(now), key=lambda m: -(now.get(m, {}).get("total", 0)))
    return {"ok": True, "latest": latest.strftime("%Y-%m-%d %H:%M") if latest else None,
            "maps": [{"id": m, "name": SEBAN_MAP_NAMES.get(m, "Mapa #%d" % m), "now": now.get(m, {}).get("total", 0),
                      "ch": now.get(m, {}).get("ch", {}), "pts": series.get(m, []),
                      "peak": max([p[1] for p in series.get(m, [])] or [0])} for m in maps]}


# ---- wydajnosc ----
def _live_system():
    out = {}
    try:
        info = {}
        with open("/proc/meminfo") as fh:
            for line in fh:
                k, _, v = line.partition(":")
                info[k] = int(v.split()[0])
        tot, avail = info.get("MemTotal", 0), info.get("MemAvailable", 0)
        out["ram_total_mb"], out["ram_used_mb"] = tot // 1024, (tot - avail) // 1024
        out["ram"] = round(100.0 * (tot - avail) / tot, 1) if tot else None
        out["swap_total_mb"] = info.get("SwapTotal", 0) // 1024
        out["swap_used_mb"] = (info.get("SwapTotal", 0) - info.get("SwapFree", 0)) // 1024
    except Exception:  # noqa: BLE001
        pass
    try:
        with open("/proc/loadavg") as fh:
            out["load"] = [float(x) for x in fh.read().split()[:3]]
        out["cpus"] = _os.cpu_count() or 1
    except Exception:  # noqa: BLE001
        pass
    try:
        def _stat():
            with open("/proc/stat") as fh:
                f = [int(x) for x in fh.readline().split()[1:]]
            return sum(f), f[3] + (f[4] if len(f) > 4 else 0)
        a, ia = _stat()
        _time.sleep(0.25)
        b2, ib = _stat()
        out["cpu"] = round(100.0 * (1 - (ib - ia) / max(1, b2 - a)), 1)
    except Exception:  # noqa: BLE001
        pass
    try:
        with open("/proc/uptime") as fh:
            out["uptime"] = int(float(fh.read().split()[0]))
    except Exception:  # noqa: BLE001
        pass
    return out


def perf_data(mod, span):
    out = {"ok": True, "live": _live_system(), "pts": [], "disk": None}
    try:
        b = _bucket(span, 200, 60)
        rows = _q(mod, "SELECT FLOOR(UNIX_TIMESTAMP(captured_at) / %s) * %s AS t, AVG(cpu_percent) AS cpu, "
                       "AVG(ram_percent) AS ram, AVG(disk_percent) AS disk, MAX(cpu_percent) AS cpu_max "
                       "FROM player.web_seban_system_snapshot WHERE captured_at >= NOW() - INTERVAL %s SECOND "
                       "GROUP BY t ORDER BY t", (b, b, span))
        out["pts"] = [[int(r["t"]), float(r["cpu"] or 0), float(r["ram"] or 0), float(r["disk"] or 0), float(r["cpu_max"] or 0)]
                      for r in rows]
        last = _q(mod, "SELECT * FROM player.web_seban_system_snapshot ORDER BY captured_at DESC LIMIT 1", one=True)
        if last:
            out["disk"] = {"pct": float(last.get("disk_percent") or 0), "used": int(last.get("disk_used_mb") or 0),
                           "total": int(last.get("disk_total_mb") or 0)}
            out["last"] = {"cpu": float(last.get("cpu_percent") or 0), "ram": float(last.get("ram_percent") or 0),
                           "ram_used": int(last.get("ram_used_mb") or 0), "ram_total": int(last.get("ram_total_mb") or 0)}
    except Exception:  # noqa: BLE001
        out["no_history"] = True
    return out


def event_history(mod):
    labels = {"chest": "Szkatułki Blasku Księżyca", "exp": "Doświadczenie", "drop": "Drop przedmiotów", "yang": "Yang",
              "tanaka": "Pirat Tanaka", "zuo": "Zuo: deszcz Metinów"}
    out = []
    for r in _q(mod, "SELECT kind, value, started_at, ended_at, chest_count, yang_extra FROM player.web_seban_event_runs "
                     "WHERE ended_at IS NOT NULL ORDER BY ended_at DESC LIMIT 25"):
        k = _ms_text(mod, r["kind"])
        base = k.partition("@")[0]
        mins = int((r["ended_at"] - r["started_at"]).total_seconds() // 60) if r.get("started_at") else 0
        res = ""
        if r.get("chest_count") is not None:
            res = "%d szkatułek" % int(r["chest_count"])
        elif r.get("yang_extra") is not None:
            res = "+%s yang" % format(int(r["yang_extra"]), ",").replace(",", " ")
        out.append({"kind": base, "label": labels.get(base, base), "value": int(r["value"] or 0),
                    "start": r["started_at"].strftime("%d.%m %H:%M"), "end": r["ended_at"].strftime("%d.%m %H:%M"),
                    "mins": mins, "result": res})
    return out



# ---------------------------------------------------------------------------
# 2.1: dymek przedmiotu (rankingi), wartosc ekwipunku, bonusy ulepszen
# ---------------------------------------------------------------------------
_PRICE_CACHE = {"at": 0.0, "p": {}}


def _attr_lines(mod, it, lang):
    market = getattr(mod, "_market", None)
    out = []
    for k in range(7):
        t, v = int(it.get("attrtype%d" % k) or 0), int(it.get("attrvalue%d" % k) or 0)
        if not t or not v:
            continue
        label = None
        try:
            label = market.apply_label(t, v, lang) if market is not None else None
        except Exception:  # noqa: BLE001
            label = None
        out.append(label or ("#%d +%d" % (t, v)))
    return out


def _socket_lines(mod, it, lang):
    out = []
    for k in range(3):
        s = int(it.get("socket%d" % k) or 0)
        if s == 1:
            out.append({"pl": "Wolne gniazdo", "en": "Empty socket"}.get(lang, "Empty socket"))
        elif s >= 28000:
            out.append(_iname(mod, s, lang))
    return out


def _base_lines(mod, vnum):
    _n, base = _proto(mod)
    b = base.get(int(vnum)) or {}
    t, st, out = b.get("type", 0), b.get("subtype", 0), []
    if b.get("level"):
        out.append("Poziom %d" % b["level"])
    if t == 1:
        out.append("Atak %d–%d" % (b.get("value3", 0), b.get("value4", 0)))
        if b.get("value1") or b.get("value2"):
            out.append("Atak magiczny %d–%d" % (b.get("value1", 0), b.get("value2", 0)))
    elif t == 2 and st in (0, 1, 2, 4) and b.get("value1"):
        out.append("Obrona %d" % b.get("value1", 0))
    market = getattr(mod, "_market", None)
    for ap in b.get("apply") or []:
        try:
            out.append(market.apply_label(ap["type"], ap["val"], "pl"))
        except Exception:  # noqa: BLE001
            out.append("#%d +%d" % (ap["type"], ap["val"]))
    return out


ITEM_COLS = ("id, `window`, pos, `count`, vnum, socket0, socket1, socket2, "
             "attrtype0, attrvalue0, attrtype1, attrvalue1, attrtype2, attrvalue2, attrtype3, attrvalue3, "
             "attrtype4, attrvalue4, attrtype5, attrvalue5, attrtype6, attrvalue6")


def item_tip(mod, pid, vnum, lang):
    rows = _q(mod, "SELECT " + ITEM_COLS + " FROM player.item WHERE owner_id=%s AND vnum=%s "
                   "AND `window` IN ('EQUIPMENT','INVENTORY') ORDER BY (`window`='EQUIPMENT') DESC LIMIT 1",
              (int(pid), int(vnum)))
    it = rows[0] if rows else {"vnum": vnum}
    return {"ok": True, "vnum": int(vnum), "name": _iname(mod, vnum, lang), "base": _base_lines(mod, vnum),
            "attrs": _attr_lines(mod, it, lang), "sockets": _socket_lines(mod, it, lang),
            "where": _ms_text(mod, it.get("window")) if rows else ""}


def market_prices(mod):
    """Cena rynkowa za sztuke: srednia z ofert w sklepach offline (na zywo), cache 2 min."""
    now = _time.time()
    if now - _PRICE_CACHE["at"] < 120:
        return _PRICE_CACHE["p"]
    prices = {}
    try:
        for r in _q(mod, "SELECT vnum, SUM(`count`) AS n, SUM(CAST(JSON_UNQUOTE(JSON_EXTRACT(ikashop_data,'$.yang')) AS UNSIGNED)) AS y "
                         "FROM player.item WHERE `window`='IKASHOP_OFFLINESHOP' AND ikashop_data IS NOT NULL AND ikashop_data<>'' "
                         "GROUP BY vnum"):
            n, y = int(r["n"] or 0), int(r["y"] or 0)
            if n and y:
                prices[int(r["vnum"])] = y / float(n)
    except Exception:  # noqa: BLE001
        pass
    if not prices:
        try:
            lt = (_q(mod, "SELECT MAX(captured_at) AS t FROM player.web_seban_shop_item_snapshot", one=True) or {}).get("t")
            if lt:
                for r in _q(mod, "SELECT vnum, SUM(total_units) AS n, SUM(total_value) AS y FROM player.web_seban_shop_item_snapshot "
                                 "WHERE captured_at=%s GROUP BY vnum", (lt,)):
                    if int(r["n"] or 0):
                        prices[int(r["vnum"])] = int(r["y"] or 0) / float(r["n"])
        except Exception:  # noqa: BLE001
            pass
    _PRICE_CACHE.update(at=now, p=prices)
    return prices


def bot_value(mod, pid):
    prices = market_prices(mod)
    npc = {}
    p = _q(mod, "SELECT account_id, gold FROM player.player WHERE id=%s", (int(pid),), one=True) or {}
    acc = int(p.get("account_id") or 0)
    rows = list(_q(mod, "SELECT `window`, vnum, `count`, ikashop_data FROM player.item WHERE owner_id=%s "
                        "AND `window` IN ('EQUIPMENT','INVENTORY','BELT_INVENTORY','DRAGON_SOUL_INVENTORY','IKASHOP_OFFLINESHOP')",
                   (int(pid),)))
    if acc:
        rows += [dict(r, window="SAFEBOX") for r in _q(mod, "SELECT vnum, `count` FROM player.item WHERE owner_id=%s "
                                                            "AND `window`='SAFEBOX'", (acc,))]
    vn = sorted({int(r["vnum"]) for r in rows})
    if vn:
        try:
            for r in _q(mod, "SELECT vnum, gold FROM player.item_proto WHERE vnum IN (" + ",".join(["%s"] * len(vn)) + ")", tuple(vn)):
                npc[int(r["vnum"])] = int(r["gold"] or 0)
        except Exception:  # noqa: BLE001
            pass
    part = {"equip": 0, "inv": 0, "safe": 0, "shop": 0}
    how = {"market": 0, "npc": 0, "none": 0, "listed": 0}
    for r in rows:
        w = _ms_text(mod, r.get("window"))
        v, n = int(r["vnum"]), int(r.get("count") or 1)
        key = {"EQUIPMENT": "equip", "SAFEBOX": "safe", "IKASHOP_OFFLINESHOP": "shop"}.get(w, "inv")
        val = None
        if key == "shop":
            try:
                val = int(json.loads(_ms_text(mod, r.get("ikashop_data")) or "{}").get("yang") or 0) or None
                if val:
                    how["listed"] += 1
            except Exception:  # noqa: BLE001
                val = None
        if val is None and v in prices:
            val = prices[v] * n
            how["market"] += 1
        if val is None and npc.get(v):
            val = npc[v] * n
            how["npc"] += 1
        if val is None:
            how["none"] += 1
            val = 0
        part[key] += int(val)
    part["total"] = part["equip"] + part["inv"] + part["safe"] + part["shop"]
    return {"ok": True, "value": part, "gold": int(p.get("gold") or 0), "how": how}


def refine_bonuses(mod, raw, lang):
    """Bonusy przedmiotu po ulepszeniu: nowy przedmiot z log.log (REFINE SUCCESS, ta sama postac i sekunda)."""
    if not raw:
        return {}
    pids = sorted({int(r["pid"] or 0) for r in raw})
    ts = [r["time"] for r in raw if r.get("time")]
    newid = {}
    try:
        for r in _q(mod, "SELECT who, time, what FROM log.log WHERE how='REFINE SUCCESS' AND who IN ("
                         + ",".join(["%s"] * len(pids)) + ") AND time BETWEEN %s AND %s",
                    tuple(pids) + (min(ts), max(ts))):
            newid[(int(r["who"]), str(r["time"]))] = int(r["what"] or 0)
    except Exception:  # noqa: BLE001
        pass
    ids = set()
    for r in raw:
        ids.add(newid.get((int(r["pid"] or 0), str(r["time"])), 0))
        ids.add(int(r.get("item_id") or 0))
    ids.discard(0)
    items = {}
    if ids:
        ids = sorted(ids)
        for it in _q(mod, "SELECT " + ITEM_COLS + " FROM player.item WHERE id IN (" + ",".join(["%s"] * len(ids)) + ")", tuple(ids)):
            items[int(it["id"])] = it
    out = {}
    for i, r in enumerate(raw):
        it = items.get(newid.get((int(r["pid"] or 0), str(r["time"])), 0)) or items.get(int(r.get("item_id") or 0))
        if it:
            out[i] = {"attrs": _attr_lines(mod, it, lang), "sockets": _socket_lines(mod, it, lang)}
    return out


