def how_label(h):
    k = re.sub(r"[\s\-]+", "_", (h or "").strip().upper())
    if k in LOG_HOW_LABELS:
        return LOG_HOW_LABELS[k]
    if k.startswith("DEAD"):
        return "Śmierci postaci"
    if k.endswith("KILL"):
        return "Zabici przeciwnicy"
    if k.startswith("PLAYERBOT_"):
        return "Inne działania botów"
    return "Inne zdarzenia"



