PAGE2_BODY = """<div class="card m2p-pg-head"><h3>{{ m2p_pg.title }}</h3><div class="m2p-ms-bar"><p class="muted" id="pgNote"></p>
<div class="m2p-rng" id="pgRng"></div></div></div><div id="m2pPage" data-page="{{ m2p_pg.page }}" data-lang="{{ curlang }}"></div>"""


def install_pages2(mod, app):
    def lang():
        try:
            return mod.lang()
        except Exception:  # noqa: BLE001
            return "pl"

    for slug, ep, key in PAGES2:
        def view(_key=key):
            return render_template_string(mod.BASE.replace("__BODY__", PAGE2_BODY),
                                          m2p_pg={"title": _l(_key, lang()), "page": _key})
        view.__name__ = ep
        app.add_url_rule("/panel/" + slug, ep, mod.login_required(view))

    def api(fn):
        def wrapped():
            try:
                return jsonify(fn())
            except Exception as exc:  # noqa: BLE001
                app.logger.exception("m2_theme api")
                return jsonify({"ok": False, "error": str(exc)[:200]})
        return wrapped

    def rng():
        return METRIC_RANGES.get(request.args.get("range", "24h"), 86400)

    routes = {
        "refines": lambda: refine_data(mod, request.args.get("kind", "ok") != "fail", lang(),
                                       max(10, min(1000, int(request.args.get("limit", "150") or 150))),
                                       int(request.args.get("plus", "0") or 0)),
        "itemshop": lambda: itemshop_data(mod, lang()),
        "items": lambda: items_data(mod, lang(), request.args.get("q", "")),
        "item_history": lambda: {"ok": True, "pts": item_history(mod, int(request.args.get("vnum", "0") or 0), rng())},
        "itemdb": lambda: itemdb_data(mod, lang(), request.args.get("q", ""),
                                      int(request.args["type"]) if request.args.get("type", "").isdigit() else None,
                                      max(0, int(request.args.get("page", "0") or 0))),
        "maps": lambda: maps_data(mod, rng()),
        "perf": lambda: perf_data(mod, rng()),
        "event_history": lambda: {"ok": True, "rows": event_history(mod)},
        "item_tip": lambda: item_tip(mod, int(request.args.get("pid", "0") or 0), int(request.args.get("vnum", "0") or 0), lang()),
        "world": lambda: _cached("world", 60, lambda: world_stats(mod)),
        "bot_value": lambda: bot_value(mod, int(request.args.get("pid", "0") or 0)),
    }
    def _restart():
        if request.method != "POST":
            st = {}
            try:
                st = mod.rates_status() or {}
            except Exception:  # noqa: BLE001
                pass
            return {"ok": True, "state": st.get("state", ""), "message": st.get("message", ""), "time": st.get("time", ""),
                    "script": bool(_os.path.exists(getattr(mod, "RATES_SCRIPT", "") or ""))}
        script = getattr(mod, "RATES_SCRIPT", "") or ""
        if not _os.path.exists(script):
            return {"ok": False, "error": "no-script"}
        try:
            mod.write_rates_status("running")
        except Exception:  # noqa: BLE001
            pass
        import subprocess as _sp
        _sp.Popen(["/bin/sh", script], stdin=_sp.DEVNULL, stdout=_sp.DEVNULL, stderr=_sp.DEVNULL,
                  close_fds=True, start_new_session=True)
        app.logger.warning("m2_theme: server restart requested from the panel")
        return {"ok": True, "state": "running"}

    for name, fn in routes.items():
        app.add_url_rule("/m2p/api/" + name, "m2p_api_" + name, mod.login_required(api(fn)))

